const toDate = (value) => (value ? new Date(value) : null);

async function main() {
  await sequelize.authenticate();

  const transaction = await sequelize.transaction();
  try {
    for (const item of PRODUCT_VARIANTS) {
      let existing = null;

      if (item.id) {
        existing = await ProductVariant.findByPk(item.id, { transaction });
      }
      if (!existing && item.sku) {
        existing = await ProductVariant.findOne({
          where: { sku: item.sku },
          transaction,
        });
      }
      if (existing) {
        continue;
      }

      await ProductVariant.create(
        {
          id: item.id,
          product_id: item.product_id,
          color: item.color,
          size: item.size,
          sku: item.sku,
          price: item.price ?? 0,
          stock_quantity: item.stock_quantity ?? 0,
          image_url: item.image_url,
          created_at: toDate(item.created_at),
          updated_at: toDate(item.updated_at),
        },
        { transaction }
      );
      console.log(
        `➕ Inserted variant: id=${item.id ?? "auto"}, sku=${item.sku ?? "n/a"}`
      );
    }

    await sequelize.query(
      "SELECT setval(pg_get_serial_sequence('product_variants','id'), (SELECT MAX(id) FROM product_variants));",
      { transaction }
    );

    await transaction.commit();
    console.log(`✅ Imported ${PRODUCT_VARIANTS.length} product variants.`);
  } catch (err) {
    await transaction.rollback();
    console.error("❌ Import product variants failed:", err);
    process.exit(1);
  } finally {
    await sequelize.close();
  }
}

main();
